#!/usr/bin/env node
// Generates the themed icon modules src/Klar/Icon/*.elm and src/Klar/Icon/Library.elm
// from the Lucide icon set (https://lucide.dev, ISC license) and scripts/icons-spec.mjs.
//
//   npm pack lucide-static           # in an empty directory, then unpack it
//   node scripts/generate-icons.mjs <directory with the unpacked lucide-static>
//
// The generated files are committed; this script only has to run when the spec
// changes. It needs no network itself. Run `npm run format` afterwards.

import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { groups } from './icons-spec.mjs';

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const lucideDir = process.argv[2];
if (!lucideDir) {
  console.error('usage: node scripts/generate-icons.mjs <unpacked lucide-static directory>');
  process.exit(2);
}
const nodes = JSON.parse(fs.readFileSync(path.join(lucideDir, 'icon-nodes.json'), 'utf8'));
const tags = JSON.parse(fs.readFileSync(path.join(lucideDir, 'tags.json'), 'utf8'));
const lucideVersion = JSON.parse(fs.readFileSync(path.join(lucideDir, 'package.json'), 'utf8')).version;

// Names that would clash with Elm keywords, with `Basics`, or with this library.
const reserved = new Set(
  `if then else case of let in type module where import exposing as port effect infix
   pi e min max not xor round floor ceiling truncate abs sqrt identity always compare clamp negate
   toFloat sin cos tan degrees radians turns modBy remainderBy view all name custom fromSvg`.split(/\s+/),
);

const coreElm = fs.readFileSync(path.join(root, 'src', 'Klar', 'Icon.elm'), 'utf8');
const coreNames = new Set([...coreElm.matchAll(/fromSvg "([a-z0-9-]+)" "/g)].map((m) => m[1]));

const camel = (kebab) => kebab.replace(/-([a-z0-9])/g, (_, c) => c.toUpperCase());
const words = (kebab) => kebab.replace(/-/g, ' ').replace(/^./, (c) => c.toUpperCase());

const attrOrder = ['d', 'cx', 'cy', 'r', 'x', 'y', 'width', 'height', 'rx', 'ry', 'x1', 'y1', 'x2', 'y2', 'points'];
function markup(name) {
  const parts = nodes[name].map(([tag, attrs]) => {
    const a = Object.entries(attrs)
      .filter(([k]) => k !== 'key')
      .map(([k, v]) => [k, k === 'fill' && v === 'currentColor' ? 'black' : String(v)]);
    a.sort(([x], [y]) => (attrOrder.indexOf(x) + 99) % 99 - (attrOrder.indexOf(y) + 99) % 99);
    for (const [k, v] of a) {
      if (/["'\\%#<>&]/.test(v)) throw new Error(`${name}: unexpected character in ${k}="${v}"`);
    }
    return `<${tag} ${a.map(([k, v]) => `${k}='${v}'`).join(' ')}/>`;
  });
  return parts.join('');
}

const seen = new Set();
const problems = [];
const modules = [];
for (const g of groups) {
  const icons = [];
  for (const lucide of g.names) {
    if (!nodes[lucide]) {
      problems.push(`${g.module}: Lucide has no icon "${lucide}"`);
      continue;
    }
    if (coreNames.has(lucide) || seen.has(lucide)) {
      problems.push(`${g.module}: "${lucide}" is already in the library`);
      continue;
    }
    const fn = camel(lucide);
    if (reserved.has(fn)) {
      problems.push(`${g.module}: "${lucide}" would be an Elm name that is not allowed (${fn})`);
      continue;
    }
    seen.add(lucide);
    const own = new Set(lucide.split('-'));
    const search = (tags[lucide] || []).filter((t) => !own.has(t)).slice(0, 4);
    icons.push({ lucide, fn, svg: markup(lucide), doc: words(lucide) + '.' + (search.length ? ` Also found as: ${search.join(', ')}.` : '') });
  }
  icons.sort((a, b) => (a.fn < b.fn ? -1 : 1));
  modules.push({ ...g, icons });
}
if (problems.length > 0) {
  console.error(problems.join('\n'));
  process.exit(1);
}

const chunk = (list, n) => Array.from({ length: Math.ceil(list.length / n) }, (_, i) => list.slice(i * n, i * n + n));
const header = `-- Generated by scripts/generate-icons.mjs from Lucide ${lucideVersion} (ISC). Do not edit by hand:
-- change scripts/icons-spec.mjs and run the script again.\n\n`;

for (const m of modules) {
  const names = m.icons.map((i) => i.fn);
  const docLines = chunk(names, 8).map((c) => `@docs ${c.join(', ')}`).join('\n');
  const body = m.icons
    .map((i) => `{-| ${i.doc}\n-}\n${i.fn} : Icon\n${i.fn} =\n    Icon.fromSvg "${i.lucide}" "${i.svg}"\n`)
    .join('\n\n');
  const src = `module Klar.Icon.${m.module} exposing (all, ${names.join(', ')})

${header}{-| ${m.title}: ${m.icons.length} icons.

Use when: you need an icon of this theme for a component that takes an Icon.
Do not use when: the everyday icon exists in \`Klar.Icon\`, or you want to browse all icons (\`Klar.Icon.Library\`).

    import Klar.Icon as Icon
    import Klar.Icon.${m.module} as ${m.module}

    Icon.view ${m.module}.${names[0]}

Every icon is a value of \`Klar.Icon.Icon\`, so \`Icon.view\`, \`Icon.sized\` and
\`Icon.labelled\` and every component that takes an icon work with it. An icon that
the application does not use is left out by \`elm make --optimize\`.

@docs all

${docLines}

-}

import Klar.Icon as Icon exposing (Icon)


{-| Every icon of this module, in alphabetical order.
-}
all : List Icon
all =
${m.icons.map((i, k) => `    ${k === 0 ? '[' : ','} ${i.fn}`).join('\n')}
    ]


${body}`;
  fs.mkdirSync(path.join(root, 'src', 'Klar', 'Icon'), { recursive: true });
  fs.writeFileSync(path.join(root, 'src', 'Klar', 'Icon', `${m.module}.elm`), src);
}

const library = `module Klar.Icon.Library exposing (Group, all, groups, count)

${header}{-| The whole icon library in one place, for galleries, pickers and tests.

Use when: you need a gallery, a picker or a test that goes through every icon.
Do not use when: the application only shows some icons (import them from their modules, or \`Klar.Icon\` for the everyday set).

Each group is a module: \`Klar.Icon\` has the everyday icons, and the other modules
(\`Klar.Icon.Arrows\`, \`Klar.Icon.Business\` and so on) hold the rest. Using this
module puts every icon in your program; the compiler cannot leave any out. An
application that only shows icons should import the icons it needs from their
modules.

@docs Group, groups, all, count

-}

${modules.map((m) => `import Klar.Icon.${m.module}`).join('\n')}
import Klar.Icon exposing (Icon)


{-| A named set of icons: a module of the library.
-}
type alias Group =
    { title : String
    , moduleName : String
    , icons : List Icon
    }


{-| The groups of the library, with the everyday icons first.
-}
groups : List Group
groups =
    [ { title = "Everyday icons", moduleName = "Klar.Icon", icons = Klar.Icon.all }
${modules.map((m) => `    , { title = "${m.title}", moduleName = "Klar.Icon.${m.module}", icons = Klar.Icon.${m.module}.all }`).join('\n')}
    ]


{-| Every icon of the library.
-}
all : List Icon
all =
    List.concatMap .icons groups


{-| How many icons the library has.
-}
count : Int
count =
    List.length all
`;
fs.writeFileSync(path.join(root, 'src', 'Klar', 'Icon', 'Library.elm'), library);

const total = modules.reduce((n, m) => n + m.icons.length, 0);
console.log(`generated ${modules.length} modules, ${total} icons (core: ${coreNames.size})`);
for (const m of modules) console.log(`  ${m.module.padEnd(14)} ${String(m.icons.length).padStart(3)}  (+${m.reserve.length} in reserve)`);
